var d = doc;
Func<Element,string,bool> filled = (e,pn) => { var p = e.LookupParameter(pn); if (p==null || !p.HasValue) { var t = d.GetElement(e.GetTypeId()); if (t==null) return false; p = t.LookupParameter(pn); if (p==null||!p.HasValue) return false; }
  var v = p.StorageType==StorageType.String ? p.AsString() : p.AsValueString(); return !string.IsNullOrWhiteSpace(v); };
var cats = new[]{BuiltInCategory.OST_Walls, BuiltInCategory.OST_Doors, BuiltInCategory.OST_Windows, BuiltInCategory.OST_Floors, BuiltInCategory.OST_Ceilings, BuiltInCategory.OST_Stairs, BuiltInCategory.OST_Railings, BuiltInCategory.OST_Rooms, BuiltInCategory.OST_Roofs, BuiltInCategory.OST_GenericModel};
var counts = cats.ToDictionary(c => c.ToString().Replace("OST_",""), c => new FilteredElementCollector(d).OfCategory(c).WhereElementIsNotElementType().GetElementCount());
var fill = new Dictionary<string,object>();
foreach (var c in new[]{BuiltInCategory.OST_Walls, BuiltInCategory.OST_Doors, BuiltInCategory.OST_Windows, BuiltInCategory.OST_Floors, BuiltInCategory.OST_Ceilings}) {
  var els = new FilteredElementCollector(d).OfCategory(c).WhereElementIsNotElementType().ToList(); if (els.Count==0) continue;
  fill[c.ToString().Replace("OST_","")] = new[]{"Type Mark","Fire Rating","OmniClass Number","Assembly Code","Description","Mark"}.ToDictionary(pn => pn, pn => Math.Round(100.0*els.Count(e=>filled(e,pn))/els.Count));
}
var genericWalls = new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_Walls).WhereElementIsNotElementType().Count(e => { var t = d.GetElement(e.GetTypeId()); return t!=null && t.Name.ToLower().Contains("generic"); });
var genericFloors = new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_Floors).WhereElementIsNotElementType().Count(e => { var t = d.GetElement(e.GetTypeId()); return t!=null && t.Name.ToLower().Contains("generic"); });
var warns = d.GetWarnings();
var topWarn = warns.GroupBy(w => w.GetDescriptionText()).OrderByDescending(g=>g.Count()).Take(6).Select(g=>new{w=g.Key.Length>80?g.Key.Substring(0,80):g.Key,n=g.Count()}).ToList();
var rooms = new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_Rooms).Cast<SpatialElement>().ToList();
var dupInst = warns.Count(w => w.GetDescriptionText().Contains("identical instances"));
var links = new FilteredElementCollector(d).OfClass(typeof(RevitLinkType)).Cast<RevitLinkType>().ToList();
int notFound = links.Count(l => !RevitLinkType.IsLoaded(d, l.Id));
var unpinnedLinks = new FilteredElementCollector(d).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>().Count(l => !l.Pinned);
return new { counts, genericWalls, genericFloors, fill, warnings = warns.Count, topWarn, dupInst, roomsTotal = rooms.Count, roomsUnplacedOrZero = rooms.Count(r => r.Area <= 0), linkTypes = links.Count, linkTypesNotLoaded = notFound, unpinnedLinkInstances = unpinnedLinks };
